// Set default values
const input = $input.first().json;
console.log('INPUT:', JSON.stringify(input, null, 2));

const parseToISO = (dateStr, isEnd = false) => {
  if (!dateStr) return null;
  if (typeof dateStr === 'string' && dateStr.includes('T') && dateStr.endsWith('Z')) return dateStr;
  if (typeof dateStr === 'string' && !dateStr.includes('T')) return dateStr + (isEnd ? 'T23:59:59.999Z' : 'T00:00:00.000Z');
  return dateStr;
};

const start_date = parseToISO(input.start_date, false) || new Date(Date.now() - 7*24*60*60*1000).toISOString();
const end_date   = parseToISO(input.end_date, true)   || new Date().toISOString();
const type       = input.type || 'company';
const device_id  = (type === 'device' && input.device_id) ? input.device_id : null;

// Para relatório de empresa: array com IDs de todos os dispositivos
const device_ids  = Array.isArray(input.device_ids) && input.device_ids.length > 0
  ? input.device_ids
  : (device_id ? [device_id] : []);

const use_all_hours  = input.use_all_hours !== false;
const selected_hours = Array.isArray(input.selected_hours) ? input.selected_hours : [];

console.log('type:', type, '| device_id:', device_id, '| device_ids:', device_ids);

return [{ json: {
  type, device_id, device_ids,
  start_date, end_date,
  company_name:  input.company_name  || 'Geral',
  device_name:   input.device_name   || input.device_id || 'Todos',
  device_code:   input.device_code   || input.device_id || '--',
  ala:           input.ala           || '--',
  use_all_hours, selected_hours
} }];

// Buscar telemetria de múltiplos dispositivos da empresa via PostgREST
const config = $('Set Defaults').first().json;
const ids = config.device_ids || [];

const inFilter = ids.length > 0 ? `device_id=in.(${ids.join(',')})` : '';
const tsFilter = `timestamp=gte.${config.start_date}&timestamp=lte.${config.end_date}`;
const url = `https://ueyizghzblngswgukfmr.supabase.co/rest/v1/telemetry?${inFilter}&${tsFilter}&order=timestamp.asc&limit=10000`;

console.log('Company query URL:', url);
console.log('Buscando para device_ids:', ids);

const ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVleWl6Z2h6YmxuZ3N3Z3VrZm1yIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ5MTAzOTcsImV4cCI6MjA5MDQ4NjM5N30.cQCkTKWbrGwO3gVYQZNmKAytls1TE3d7LddrgSc8QqA';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: {
      'apikey': ANON_KEY,
      'Authorization': `Bearer ${ANON_KEY}`,
      'Content-Type': 'application/json'
    }
  });

  if (Array.isArray(response)) {
    console.log('Company telemetry: encontrados', response.length, 'registros');
    return response.map(r => ({ json: r }));
  }
  console.warn('Resposta não é array:', typeof response);
  return [{ json: { _warning: 'Resposta inválida', _empty: true } }];
} catch(e) {
  console.error('Erro busca company:', e.message);
  return [{ json: { _warning: 'Erro na busca: ' + e.message, _empty: true } }];
}

// Merge results from both paths and normalize
const config = $('Set Defaults').first().json;
let items = [];

try {
  if (config.type === 'device') {
    items = $('Buscar Telemetry').all();
  } else {
    // Para company: HTTP Request retorna array direto no body
    const companyItems = $('Buscar Telemetry (Company)').all();
    if (companyItems && companyItems.length > 0) {
      const first = companyItems[0].json;
      // HTTP Request retorna array no json quando a resposta é JSON array
      if (Array.isArray(first)) {
        items = first.map(r => ({ json: r }));
      } else {
        items = companyItems;
      }
    }
  }
} catch(e) { console.error('Validar Dados erro:', e.message); }

if (!items || items.length === 0) {
  console.warn('Nenhum dado encontrado para os filtros informados.');
  return [{ json: { _warning: 'Sem dados no período', _empty: true } }];
}

// Buscar informações de devices e tenants via PostgREST
const ANON_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVleWl6Z2h6YmxuZ3N3Z3VrZm1yIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ5MTAzOTcsImV4cCI6MjA5MDQ4NjM5N30.cQCkTKWbrGwO3gVYQZNmKAytls1TE3d7LddrgSc8QqA';
const headers = { 'apikey': ANON_KEY, 'Authorization': `Bearer ${ANON_KEY}`, 'Content-Type': 'application/json' };

try {
  const devicesRes = await this.helpers.httpRequest({ method: 'GET', url: 'https://ueyizghzblngswgukfmr.supabase.co/rest/v1/devices_status?select=id,name,location,tenant_id', headers: headers, json: true });
  let tenantsRes = [];
  try {
    tenantsRes = await this.helpers.httpRequest({ method: 'GET', url: 'https://ueyizghzblngswgukfmr.supabase.co/rest/v1/tenants?select=id,name', headers: headers, json: true });
  } catch(e) { console.warn('Não foi possível buscar tenants', e); }

  const tenantMap = {};
  if (Array.isArray(tenantsRes)) {
    tenantsRes.forEach(t => tenantMap[t.id] = t.name);
  }

  const deviceMap = {};
  if (Array.isArray(devicesRes)) {
    devicesRes.forEach(d => {
       deviceMap[d.id] = {
         device_name: d.name || d.id,
         location: d.location || 'Sem ala',
         tenant_id: d.tenant_id,
         tenant_name: tenantMap[d.tenant_id] || 'Empresa Desconhecida'
       };
    });
  }

  // Enriquecer items com infos
  items = items.map(item => {
    const info = deviceMap[item.json.device_id] || {};
    return {
      json: {
        ...item.json,
        device_name: info.device_name || item.json.device_id,
        location: info.location || item.json.location || 'Sem ala',
        tenant_name: info.tenant_name || config.company_name || 'Geral'
      }
    };
  });
} catch(e) {
  console.error('Erro ao enriquecer dados com device/tenant info', e);
}

console.log('Validar Dados: retornando', items.length, 'registros');
return items;

// Process and prepare all data for HTML Report
let html_content = '';
let stats = {
  total_records: 0, temp_avg: '--', temp_max: '--', temp_min: '--',
  humidity_avg: '--', battery_avg: '--', voltage_avg: '--',
  device_name: 'Todos', device_code: '--', company_name: 'Geral', ala: 'Não informada',
  period: 'Período não informado', report_date: '', year: new Date().getFullYear(), month: ''
};

try {
  const telemetryData = $input.all();
  const config = $('Set Defaults').first().json;

  const formatDate = (isoStr) => {
    if (!isoStr) return '';
    return new Date(isoStr).toLocaleDateString('pt-BR', { timeZone: 'UTC' });
  };

  stats.device_name = config.device_name || 'Todos os dispositivos';
  stats.device_code = config.device_code || '--';
  stats.company_name = config.company_name || 'Geral';
  stats.ala = config.ala || '--';
  stats.period = `${formatDate(config.start_date)} a ${formatDate(config.end_date)}`;
  stats.report_date = formatDate(config.start_date);
  const reportDate = config.start_date ? new Date(config.start_date) : new Date();
  stats.year = reportDate.getFullYear();
  stats.month = reportDate.toLocaleString('pt-BR', { month: 'long', timeZone: 'UTC' });

  // Filtrar por horários selecionados
  const use_all_hours = config.use_all_hours !== false;
  const selected_hours = Array.isArray(config.selected_hours) ? config.selected_hours : [];
  const selectedHourNums = selected_hours.map(h => parseInt(h.split(':')[0]));

  let data = [];
  if (telemetryData && telemetryData.length > 0) {
    let allData = telemetryData
      .map(t => t.json)
      .filter(r => r && r.timestamp && !r._empty)
      .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

    data = (!use_all_hours && selectedHourNums.length > 0)
      ? allData.filter(row => selectedHourNums.includes(parseInt(new Date(row.timestamp).toLocaleTimeString('pt-BR', { hour: '2-digit', hour12: false, timeZone: 'UTC' }))))
      : allData;

    const avg = arr => arr.length ? (arr.reduce((a, b) => a + b, 0) / arr.length).toFixed(1) : '0';
    const temps      = data.map(d => d.temperature).filter(v => v != null);
    const humidities = data.map(d => d.humidity).filter(v => v != null);
    const batteries  = data.map(d => d.battery).filter(v => v != null);
    const voltages   = data.map(d => d.voltage).filter(v => v != null);

    stats.total_records  = data.length;
    stats.temp_avg       = avg(temps);
    stats.temp_max       = temps.length ? Math.max(...temps).toFixed(1) : '--';
    stats.temp_min       = temps.length ? Math.min(...temps).toFixed(1) : '--';
    stats.humidity_avg   = avg(humidities);
    stats.battery_avg    = avg(batteries);
    stats.voltage_avg    = avg(voltages);
  }

  const companyGroups = {};
  data.forEach(linha => {
    const compName = linha.tenant_name || config.company_name || 'Geral';
    const dId = linha.device_id || 'Desconhecido';
    const dName = linha.device_name || dId;
    const dAla = linha.location || '--';
    if (!companyGroups[compName]) companyGroups[compName] = {};
    if (!companyGroups[compName][dId]) companyGroups[compName][dId] = { name: dName, ala: dAla, data: [] };
    companyGroups[compName][dId].data.push(linha);
  });

  const compNames = Object.keys(companyGroups).sort();

  compNames.forEach((compName, cIdx) => {
    // Início do Bloco da Empresa
    html_content += `<div class="company-block" ${cIdx > 0 ? "style='page-break-before: always; margin-top: 40px;'" : ""}>`;

    // Cabeçalho Identidade da Empresa
    html_content += `
      <div class="header">
        <div class="header-info">
          <h1>Relatório de Telemetria — ${compName}</h1>
          <p>Período: ${stats.period}</p>
        </div>
      </div>
      <table class="table-header-group">
        <thead>
          <tr>
            <th class="th-section dia" rowspan="2">Dia</th>
            <th class="th-section manha" colspan="4">🌅 Manhã (00h – 11h59)</th>
            <th class="th-section sep" rowspan="2"> </th>
            <th class="th-section tarde" colspan="4">🌇 Tarde (12h – 23h59)</th>
          </tr>
          <tr>
            <th class="th-col">Hora</th><th class="th-col">Máx °C</th><th class="th-col">Mín °C</th><th class="th-col">Atual °C</th>
            <th class="th-col">Hora</th><th class="th-col">Máx °C</th><th class="th-col">Mín °C</th><th class="th-col">Atual °C</th>
          </tr>
        </thead>
        <tbody>
    `;

    const devicesInCompany = companyGroups[compName];
    const devIds = Object.keys(devicesInCompany);

    devIds.forEach(dId => {
      const dev = devicesInCompany[dId];
      const deviceData = dev.data;

      // Linha de identificação do dispositivo
      html_content += "<tr><td colspan='10' class='device-section-header'>📍 Dispositivo: <strong>" + dev.name + "</strong> (" + dev.ala + ") &nbsp;|&nbsp; " + deviceData.length + " leituras</td></tr>";

      const diasAgrupados = {};
      deviceData.forEach(linha => {
        const dt = new Date(linha.timestamp);
        const dia = dt.toLocaleDateString('pt-BR', { timeZone: 'UTC' });
        if (!diasAgrupados[dia]) diasAgrupados[dia] = { dia, ts: dt.getTime(), manhas: [], tardes: [] };

        const entry = {
          HORA: dt.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'UTC' }),
          TEMP: linha.temperature != null ? linha.temperature.toFixed(1) : '--',
          MAX:  linha.temp_max    != null ? linha.temp_max.toFixed(1)    : '--',
          MIN:  linha.temp_min    != null ? linha.temp_min.toFixed(1)    : '--'
        };
        if (parseInt(dt.toLocaleTimeString('pt-BR', { hour: '2-digit', hour12: false, timeZone: 'UTC' })) >= 12) diasAgrupados[dia].tardes.push(entry);
        else                     diasAgrupados[dia].manhas.push(entry);
      });

      Object.values(diasAgrupados).sort((a, b) => a.ts - b.ts).forEach((grupo, gIdx, gArr) => {
        const maxLen = Math.max(grupo.manhas.length, grupo.tardes.length, 1);
        for (let i = 0; i < maxLen; i++) {
          const m = grupo.manhas[i] || { HORA: '', TEMP: '', MAX: '', MIN: '' };
          const t = grupo.tardes[i] || { HORA: '', TEMP: '', MAX: '', MIN: '' };
          html_content += "<tr>" +
            "<td class='dia-cell'>" + (i === 0 ? grupo.dia : '') + "</td>" +
            "<td>" + m.HORA + "</td><td>" + m.MAX + "</td><td>" + m.MIN + "</td><td>" + m.TEMP + "</td>" +
            "<td class='sep'></td>" +
            "<td>" + t.HORA + "</td><td>" + t.MAX + "</td><td>" + t.MIN + "</td><td>" + t.TEMP + "</td>" +
            "</tr>";
        }
        if (gIdx < gArr.length - 1) {
          html_content += '<tr class="day-sep-row"><td colspan="10" class="day-separator"></td></tr>';
        }
      });
    });

    html_content += '</tbody></table></div>';
  });

} catch (e) {
  console.error('Processar Dados erro:', e.message);
}

return [{ json: { stats, html_content } }];

// Extrair binário para base64
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64String = binaryData.toString('base64');

return [{
  json: {
    pdf_base64: base64String,
    fileName: 'relatorio_telemetria.pdf',
    mimeType: 'application/pdf'
  }
}]

// Build response
const stats = $('Processar Dados').first().json.stats;
const config = $('Set Defaults').first().json;
const pdf_data = $('Extract PDF').first().json;

return [{
  json: {
    status: 'success',
    message: 'Relatório processado com sucesso',
    type: config.type,
    period: { start: config.start_date, end: config.end_date },
    pdf_base64: pdf_data.pdf_base64,
    stats: {
      total_records: stats.total_records,
      temp_avg: stats.temp_avg,
      temp_max: stats.temp_max,
      temp_min: stats.temp_min
    }
  }
}];
